using Command = std::variant<SetTempo, SetKey, SetStyle, SetTimeSignature, SetSwing, RenameProject, AddChannel, UpdateChannel, RemoveChannel, UpdateInstrument, AddSamplerLayer, UpdateSamplerLayer, RemoveSamplerLayer, AddPattern, UpdatePattern, RemovePattern, AddNotes, RemoveNotes, SetNotes, InsertTrack, UpdateTrack, RemoveTrack, AddClip, UpdateClip, RemoveClip, AddInsert, UpdateInsert, RemoveInsert, AddEffect, UpdateEffect, RemoveEffect, MoveEffect, AddSend, UpdateSend, RemoveSend, Patch>;

inline void readValue (Reader& r, const Json& j, Command& out)
{
    if (! j.is_object())
        r.fail ("expected object");

    std::string tag;
    r.required (j, "type", [&] (const Json& v) { readValue (r, v, tag); });

    if (tag == "setTempo") { readValue (r, j, out.emplace<SetTempo>()); return; }
    if (tag == "setKey") { readValue (r, j, out.emplace<SetKey>()); return; }
    if (tag == "setStyle") { readValue (r, j, out.emplace<SetStyle>()); return; }
    if (tag == "setTimeSignature") { readValue (r, j, out.emplace<SetTimeSignature>()); return; }
    if (tag == "setSwing") { readValue (r, j, out.emplace<SetSwing>()); return; }
    if (tag == "renameProject") { readValue (r, j, out.emplace<RenameProject>()); return; }
    if (tag == "addChannel") { readValue (r, j, out.emplace<AddChannel>()); return; }
    if (tag == "updateChannel") { readValue (r, j, out.emplace<UpdateChannel>()); return; }
    if (tag == "removeChannel") { readValue (r, j, out.emplace<RemoveChannel>()); return; }
    if (tag == "updateInstrument") { readValue (r, j, out.emplace<UpdateInstrument>()); return; }
    if (tag == "addSamplerLayer") { readValue (r, j, out.emplace<AddSamplerLayer>()); return; }
    if (tag == "updateSamplerLayer") { readValue (r, j, out.emplace<UpdateSamplerLayer>()); return; }
    if (tag == "removeSamplerLayer") { readValue (r, j, out.emplace<RemoveSamplerLayer>()); return; }
    if (tag == "addPattern") { readValue (r, j, out.emplace<AddPattern>()); return; }
    if (tag == "updatePattern") { readValue (r, j, out.emplace<UpdatePattern>()); return; }
    if (tag == "removePattern") { readValue (r, j, out.emplace<RemovePattern>()); return; }
    if (tag == "addNotes") { readValue (r, j, out.emplace<AddNotes>()); return; }
    if (tag == "removeNotes") { readValue (r, j, out.emplace<RemoveNotes>()); return; }
    if (tag == "setNotes") { readValue (r, j, out.emplace<SetNotes>()); return; }
    if (tag == "insertTrack") { readValue (r, j, out.emplace<InsertTrack>()); return; }
    if (tag == "updateTrack") { readValue (r, j, out.emplace<UpdateTrack>()); return; }
    if (tag == "removeTrack") { readValue (r, j, out.emplace<RemoveTrack>()); return; }
    if (tag == "addClip") { readValue (r, j, out.emplace<AddClip>()); return; }
    if (tag == "updateClip") { readValue (r, j, out.emplace<UpdateClip>()); return; }
    if (tag == "removeClip") { readValue (r, j, out.emplace<RemoveClip>()); return; }
    if (tag == "addInsert") { readValue (r, j, out.emplace<AddInsert>()); return; }
    if (tag == "updateInsert") { readValue (r, j, out.emplace<UpdateInsert>()); return; }
    if (tag == "removeInsert") { readValue (r, j, out.emplace<RemoveInsert>()); return; }
    if (tag == "addEffect") { readValue (r, j, out.emplace<AddEffect>()); return; }
    if (tag == "updateEffect") { readValue (r, j, out.emplace<UpdateEffect>()); return; }
    if (tag == "removeEffect") { readValue (r, j, out.emplace<RemoveEffect>()); return; }
    if (tag == "moveEffect") { readValue (r, j, out.emplace<MoveEffect>()); return; }
    if (tag == "addSend") { readValue (r, j, out.emplace<AddSend>()); return; }
    if (tag == "updateSend") { readValue (r, j, out.emplace<UpdateSend>()); return; }
    if (tag == "removeSend") { readValue (r, j, out.emplace<RemoveSend>()); return; }
    if (tag == "patch") { readValue (r, j, out.emplace<Patch>()); return; }

    r.fail ("unknown type \"" + tag + "\"");
}

inline Json toJson (const Command& v)
{
    return std::visit ([] (auto& alt) { return toJson (alt); }, v);
}

/** One applied change. Entries form a tree: undo moves to the parent, new changes after an undo start a branch. */
struct HistoryEntry
{
    /** Sequence number, starting at 1. */
    int64_t id {};
    /** Entry this one was applied on top of; absent for the first change. */
    std::optional<int64_t> parent;
    /** Milliseconds since the Unix epoch. */
    int64_t time {};
    /** Who made the change, e.g. "ui", "agent" or "cli". */
    std::string origin;
    /** Changes with the same group (e.g. one agent request) undo together. */
    std::optional<std::string> group;
    /** Short human-readable description. */
    std::string label;
    std::vector<Command> commands;
    std::vector<PatchOp> forward;
    std::vector<PatchOp> inverse;

    bool operator== (const HistoryEntry&) const = default;
};

inline void readValue (Reader& r, const Json& j, HistoryEntry& out)
{
    r.expectObject (j, { "id", "parent", "time", "origin", "group", "label", "commands", "forward", "inverse" });

    r.required (j, "id", [&] (const Json& v) { readValue (r, v, out.id); r.checkMin (out.id, 1); });
    r.optional (j, "parent", [&] (const Json& v) { readValue (r, v, out.parent.emplace()); r.checkMin (*out.parent, 1); });
    r.required (j, "time", [&] (const Json& v) { readValue (r, v, out.time); r.checkMin (out.time, 0); });
    r.required (j, "origin", [&] (const Json& v) { readValue (r, v, out.origin); });
    r.optional (j, "group", [&] (const Json& v) { readValue (r, v, out.group.emplace()); });
    r.required (j, "label", [&] (const Json& v) { readValue (r, v, out.label); });
    r.required (j, "commands", [&] (const Json& v) { readValue (r, v, out.commands); });
    r.required (j, "forward", [&] (const Json& v) { readValue (r, v, out.forward); });
    r.required (j, "inverse", [&] (const Json& v) { readValue (r, v, out.inverse); });
}

inline Json toJson (const HistoryEntry& v)
{
    auto j = Json::object();
    j["id"] = toJson (v.id);

    if (v.parent)
        j["parent"] = toJson (*v.parent);

    j["time"] = toJson (v.time);
    j["origin"] = toJson (v.origin);

    if (v.group)
        j["group"] = toJson (*v.group);

    j["label"] = toJson (v.label);
    j["commands"] = toJson (v.commands);
    j["forward"] = toJson (v.forward);
    j["inverse"] = toJson (v.inverse);
    return j;
}

